import { requireUser } from "@/lib/auth";
import { createBusiness } from "@/lib/business";
import { body, route } from "@/lib/http";
import { rateLimit } from "@/lib/ratelimit";
import { createBusinessSchema } from "@/lib/schemas";

export const POST = route(async (req) => {
  const user = await requireUser();
  await rateLimit(`business:create:${user.id}`, 10, 3600);
  const input = await body(req, createBusinessSchema);
  const business = await createBusiness(user.id, input);
  return { business: { id: business.id, slug: business.slug, name: business.name } };
});
