import { q } from "./db";
import { AppError } from "./errors";

/**
 * Fixed-window rate limit stored in PostgreSQL, so it holds across server instances.
 * Throws a 429 AppError when the limit is exceeded.
 */
export async function rateLimit(key: string, limit: number, windowSec: number): Promise<void> {
  if (process.env.RATE_LIMIT_DISABLED === "1") return;
  const rows = await q<{ count: number }>(
    `INSERT INTO rate_limits (key, window_start, count)
     VALUES ($1, to_timestamp(floor(extract(epoch from now()) / $2) * $2), 1)
     ON CONFLICT (key, window_start) DO UPDATE SET count = rate_limits.count + 1
     RETURNING count`,
    [key, windowSec],
  );
  if (Math.random() < 0.01) {
    q("DELETE FROM rate_limits WHERE window_start < now() - interval '1 day'").catch(() => {});
  }
  if (rows[0].count > limit) {
    throw new AppError("rate_limited", "Too many requests. Please wait a moment and try again.", 429);
  }
}
