import { createCipheriv, createDecipheriv, createHash, createHmac, hkdfSync, randomBytes, scrypt as _scrypt, timingSafeEqual } from "node:crypto";
import { promisify } from "node:util";
import { env } from "./env";

const scrypt = promisify(_scrypt) as (pw: string, salt: Buffer, len: number) => Promise<Buffer>;

export const randomToken = (bytes = 32) => randomBytes(bytes).toString("base64url");
export const sha256 = (s: string) => createHash("sha256").update(s).digest("hex");

// ---- passwords (scrypt, per-user salt) -------------------------------------
export async function hashPassword(password: string): Promise<string> {
  const salt = randomBytes(16);
  const key = await scrypt(password, salt, 64);
  return `scrypt$${salt.toString("base64url")}$${key.toString("base64url")}`;
}

export async function verifyPassword(password: string, stored: string): Promise<boolean> {
  const [scheme, saltB64, keyB64] = stored.split("$");
  if (scheme !== "scrypt" || !saltB64 || !keyB64) return false;
  const expected = Buffer.from(keyB64, "base64url");
  const actual = await scrypt(password, Buffer.from(saltB64, "base64url"), expected.length);
  return timingSafeEqual(actual, expected);
}

// ---- ticket tokens -----------------------------------------------------------
// token = base64url(ticket uuid, 16 bytes) + "." + base64url(HMAC-SHA256(secret, uuid), 24 bytes)
// The uuid is random and says nothing about the customer; the signature lets the server
// reject forged or guessed tokens before touching the database.
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;

function sign(ticketId: string): string {
  return createHmac("sha256", env.ticketSecret).update(`ticket:${ticketId}`).digest().subarray(0, 24).toString("base64url");
}

export function ticketToken(ticketId: string): string {
  const raw = Buffer.from(ticketId.replace(/-/g, ""), "hex").toString("base64url");
  return `${raw}.${sign(ticketId)}`;
}

/** Returns the ticket id if the token is well-formed and correctly signed, otherwise null. */
export function verifyTicketToken(token: string): string | null {
  if (typeof token !== "string" || token.length > 80) return null;
  const [raw, sig] = token.split(".");
  if (!raw || !sig) return null;
  const hex = Buffer.from(raw, "base64url").toString("hex");
  if (hex.length !== 32) return null;
  const id = `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
  if (!UUID_RE.test(id)) return null;
  const a = Buffer.from(sig);
  const b = Buffer.from(sign(id));
  if (a.length !== b.length || !timingSafeEqual(a, b)) return null;
  return id;
}

/** Accepts a raw token or a full ticket URL (what the QR code contains). */
export function extractTicketToken(scanned: string): string {
  const s = scanned.trim();
  const m = s.match(/\/t\/([A-Za-z0-9_-]+\.[A-Za-z0-9_-]+)/);
  return m ? m[1] : s;
}

// ---- booking references ------------------------------------------------------
const REF_ALPHABET = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ"; // no 0/O/1/I
export function newReference(): string {
  const b = randomBytes(6);
  let out = "";
  for (let i = 0; i < 6; i++) out += REF_ALPHABET[b[i] % REF_ALPHABET.length];
  return out;
}
export const normalizeReference = (s: string) => s.toUpperCase().replace(/[^A-Z0-9]/g, "");

// ---- secrets at rest -----------------------------------------------------------
// Third-party credentials saved by a business (e.g. a WhatsApp access token) are encrypted with
// AES-256-GCM under a key derived from SECRETS_KEY (or TICKET_SECRET when that is not set).
function secretsKey(): Buffer {
  return Buffer.from(hkdfSync("sha256", process.env.SECRETS_KEY || env.ticketSecret, "abc-secrets-v1", "integration-credentials", 32));
}
export function encryptSecret(plain: string): string {
  const iv = randomBytes(12);
  const c = createCipheriv("aes-256-gcm", secretsKey(), iv);
  const body = Buffer.concat([c.update(plain, "utf8"), c.final()]);
  return `v1.${iv.toString("base64url")}.${c.getAuthTag().toString("base64url")}.${body.toString("base64url")}`;
}
export function decryptSecret(stored: string): string {
  const [v, iv, tag, body] = stored.split(".");
  if (v !== "v1" || !iv || !tag || !body) throw new Error("Unreadable stored secret");
  const d = createDecipheriv("aes-256-gcm", secretsKey(), Buffer.from(iv, "base64url"));
  d.setAuthTag(Buffer.from(tag, "base64url"));
  return Buffer.concat([d.update(Buffer.from(body, "base64url")), d.final()]).toString("utf8");
}
